  str_book_title_skin_1044 = "Peacekeeping Speech",
  str_book_title_skin_1045 = "The Lonesome Apex",
  str_book_title_skin_1046 = "Black Rose Leader",
  str_book_title_skin_1047 = "The Neverending Song",
  str_book_title_skin_1048 = "Listen to Me!",
  str_book_title_skin_1049 = "Special Solo",
  str_book_title_skin_1050 = "Quantitative Makeup",
  str_book_title_skin_1051 = "Letter from the Sky",
  str_book_title_skin_1052 = "Michael the Crush",
  str_book_title_skin_1053 = "Clairvoyance",
  str_book_title_skin_1054 = "Can't Let Go",
  str_book_title_skin_1055 = "A Giant Dragon!",
  str_book_title_skin_1056 = "Easy Prey",
  str_book_title_skin_1057 = "Petal Dirge",
  str_book_title_skin_1058 = "Please Don't be Afraid",
  str_book_title_skin_1059 = "Magic Potion is Ready",
  str_book_title_skin_1060 = "Guardians Gathering",
  str_book_title_skin_1061 = "\"Cat Rinne\"",
  str_book_title_skin_1062 = "Serene Coastline",
  str_book_title_skin_1063 = "Dandelion's Wish",
  str_book_title_skin_1064 = "Underwater Ruin Exploration",
  str_book_title_skin_1065 = "Courier and Drift Bottle",
  str_book_title_skin_1066 = "Glittering Summer",
  str_book_title_skin_1067 = "Drifting Mirage",
  str_book_title_saiji_20001 = "Under the Sunlight I",
  str_book_title_saiji_20002 = "Under the Sunlight II",
  str_book_title_saiji_20003 = "Innocent Reverie",
  str_book_title_saiji_20004 = "Grand Juggernaut",
  str_book_title_saiji_20005 = "Ashen Petals",
  str_book_title_saiji_20006 = "Dawn's Caress I",
  str_book_title_saiji_20007 = "Dawn's Caress II",
  str_book_title_saiji_20101 = "Beyond Reach I",
  str_book_title_saiji_20102 = "Beyond Reach II",
  str_book_title_saiji_20103 = "Beyond Reach III",
  str_book_title_saiji_20104 = "Reflection in the Pool",
  str_book_title_saiji_20105 = "Thorns in Motion I",
  str_book_title_saiji_20106 = "Thorns in Motion II",
  str_book_title_saiji_20107 = "Court Adjourned I",
  str_book_title_saiji_20108 = "Court Adjourned II",
  str_book_info1001 = "Dormant underground for 17 years, you and Soroz depended on each other. The results of the routine maintenance told you that initiating the Colossus this time was bound to fail, just like the countless attempts before...",
  str_book_info1002 = "But things seemed different today with the sudden appearance of an intruder. Insight is your special ability as a Caelestite, and with this talent, you bear the burden of avenging your tribe...",
  str_book_info1003 = "There was no longer peace in the Colossus. With the invasion of Kraken, a high-level Eclipsite, your task of breaking through became more difficult. Could you demonstrate the capability a Navigator should have when facing a strong enemy for the first time?",
  str_book_info1004 = "Just as you stepped into a new world, the Eclipsites were bearing down on you. How on earth did they appear here? You were running out of time, so you had to return to the Colossus and find another way out...",
  str_book_info1005 = "Facing the familiar control panel, you decided to involve Vice in the startup sequence. You show Vice how to play and prepare to complete the duet together.",
  str_book_info1006 = "Facing the familiar control panel, you decided to involve Vice in the startup sequence. You show Vice how to play and prepare to complete the duet together.",
  str_book_info1007 = "Facing the familiar control panel, you decided to involve Vice in the startup sequence. You show Vice how to play and prepare to complete the duet together.",
  str_book_info1008 = "With Vice's help, you finally managed to activate the Colossus. As power surged through like how the Aurora flows, the Colossus slowly rose to the surface. Just wait a little more and you would be well out of danger.",
  str_book_info1009 = "After activating the Colossus, memories from the past flooded back; it was the day your people were destroyed in Eraveil 17 years ago. Among all the images you saw, a figure that you would never forget came into view...",
  str_book_info1010 = "Danger was far from over. With the defeat of the Sand Kraken, another high-level Eclipsite, Nozard, had vowed to destroy you, and more enemies were starting to gather around Soroz, ready to finish you off while it was warming up...",
  str_book_info1011 = "After warming up, Soroz's energy flowed through its body once again. It stretched its wings and brought you out of the restraints of darkness, back to the sky. The enemies were shaken off like dust, trembling amidst the roar of Soroz proclaiming its resurrection...",
  str_book_info1012 = "Soroz is forced to make an emergency landing in the wilderness after getting hurt from the battle and flying for the first time in a while... Just as you and Vice are arguing, the Eclipsites invade...",
  str_book_info1013 = "Rediesel Wrench... The crazy bunch of survivalists you chanced upon really opened your eyes regarding survival, companionship, and living your own life. More specifically, their cooking is really bad.",
  str_book_info1014 = "In the habitable zone between light and darkness, people fighting to protect their homes. Just like Charon said, aside from Illumina, there are more Aurorians and people out there fighting for what they hold dear.",
  str_book_info1015 = "Nozard appeared again, this time commanding more Eclipsites than ever before. The temporary shelter, Undercity 28, was left in ruins by a surprise attack. As it fell, a new chapter began...",
  str_book_info1016 = "Nozard was still in hot pursuit. To cover your retreat, Charon was besieged by the Eclipsites. He pressed the self-destructing button, the Red Key, to stop you from attempting anything foolish. You had no choice but to leave...",
  str_book_info1017 = "Undercity 28 was reduced to ruins in a violent explosion. As you mourned the loss of Charon, a familiar figure sprang into view. It was Charon himself, who had managed to escape in a grandiose perfect ending...",
  str_book_info1018 = "Just as you were about to relax, you received a distress call from what appeared to be a compatriot. After arriving at the destination, you were attacked by Colossus Guardians, Philex and Vani, who seemed to be controlled by a higher power...",
  str_book_info1019 = "Under Mendelson's guidance, you reached the bridge and defeated Tabaad, with Hiiro striking the final blow. Zakura swept across the sky with cherry blossoms, and this beautiful sight was the last thing Mendelson remembered...",
  str_book_info1020 = "According to Mendelson's final words, you must prevent an enemy named Schummer from finding the first item: Think Tank Module. It was your first visit to Lumopolis, the center of civilization in Astra.",
  str_book_info1021 = "Since you don't have access to Lumopolis, you must pass through Lower Lumopolis. It might be different from anything you can imagine. Peril permeates the air. The trip probably won't be a smooth one.",
  str_book_info1022 = "You were personally received by Carleen, the Captain of the Lumopolis Guardians, as a result of Vice's prior letter of instructions. Although this unsmiling young girl was once Vice's schoolmate, she averted her gaze and hardly paid any attention to you...",
  str_book_info1023 = "The troublemakers, Shelt and Shire, fled to Uptown but were mercilessly intercepted by you. These two Eclipsites were ready for a fight, but they had no idea of the price they were about to pay...",
  str_book_info1024 = "You gave a summary of Schummer's plan along with the Lumopolis incident at the assembly, but the Illumina Federation officers were unable to provide support for some reason. It seemed that you had to handle the battle of the next module on your own.",
  str_book_info1025 = "When arrived at where the second Component had been hidden, as shown in your data, you suddenly found yourself surrounded by a strange sensation lying somewhere between an illusion and a bewitching sound—mysterious reverberations that filled you with a deep sense of reverence...",
  str_book_info1026 = "To obtain the second module, you established a link with another long-dead Colossus. Visions of former Caelestites appeared before you, and their thoughts started seeping into your mind like a delayed symphony.",
  str_book_info1027 = "To save Gronru, you made a deal with Schummer and handed over the second module. Unexpectedly, Schummer kept her side of the bargain, just because as a former compatriot, she seemed to have some measure of pity for you...",
  str_book_info1028 = "The final module was located in the mysterious Whispering Corridor, but time is ticking and you have to quickly make a move. It's an underground vault filled with mysterious objects, and you knew nothing about what to expect there...",
  str_book_info1029 = "The entrance of Whispering Corridor swallowed the sunlight whole like a nameless beast, and the spiral staircase gave you a sense of foreboding. If Schummer was already here, you need to pick up the pace...",
  str_book_info1030 = "Gertzurde, who teamed up with Shelt to steal the first module, was finally defeated by you. Upon learning the truth behind Shelt's death, his eyes filled with disbelief, and it felt like a part of him died, while another was ignited...",
  str_book_info1031 = "In the depths of the Whispering Corridor, Schummer moved to deadly attack, but Gertzurde resolutely stood in front of you. He paled as the color of life drained from him, but this was no time to mourn or sympathize. There was still work to do.",
  str_book_info1032 = "With all three modules, Schummer led the black Colossus in an all-out assault on Lumopolis. Although the fortified Lumina Shield blocked it out, the horn of blasphemy had resounded through the air...",
  str_book_info1033 = "By working together with the officer of the Illumina Federation, the giant sandworm, Mara Sol, which tried to invade Lumopolis, was completely defeated. There might be a lull in the enemy's assault for now, but a bigger crisis was yet to come...",
  str_book_info1034 = "A vengeful Schummer attacked Soroz, and you were forced to put aside the crisis in Lumopolis, quickly returning to the Colossus. It was a scene that should have ended 17 years ago; the black and white Colossus locked in battle again...",
  str_book_info1035 = "A mysterious hooded man stood beside Schummer, the Great Aviduz. At Vivian's reproach, he revealed his face, and a name inextricably linked to the Illumina Federation: Forsakin...",
  str_book_info1036 = "Before more can be asked, Schummer was fully charged, and its unknown force held everyone down onto the ground. In the face of such an unstoppable force, Vivian decided to take a risky move...",
  str_book_info1037 = "\"The people around here are so noisy. All they do is talk nonsense. Blah, blah, blah, blah, blah...\"",
  str_book_info1038 = "At Faust's behest, Vice took the strange object known as the \"seed\" from you, said to be both responsible for transforming creatures into Apostles of Darkness, and a medium for conferring evil power...",
  str_book_info1039 = "\"Why won't you just accept your weakness? Why won't you kneel down before real power?\"",
  str_book_info1040 = "The Lumina cannon Damocles, the ultimate weapon of Lumopolis, attacked Aviduz with a terrifying roar, even at the price of putting the city at risk...",
  str_book_info1041 = "The beam emanating from Damocles shifted unexpectedly, and Carleen, who had scant Lumina remaining, seemed unable to finish guiding it alone. At that moment, Schwartz, City Lord of Lumopolis, appeared behind her. Together, the two of them dealt the final blow to Schummer.",
  str_book_info1042 = "Thanks to your mental suppression, Aviduz failed to avoid the light beam and was penetrated in an instant. Time seemed to stand still, and everyone stopped dead in their tracks to witness the end of the Black Colossus...",
  str_book_info1043 = "It's a real surprise that a high-level Eclipsite lives in Dungeon No. 80 at the edge of the Eternal Night. Its emergence is beyond everyone's expectations, and it also disrupts Vice and the Navigator's efforts to repair the Soroz.",
  str_book_info1044 = "She has already missed her opportunity once, and she doesn't want to give up this time. It's just that when the mind of her old brother-in-arms is clouded by rage and hatred, the memories of things he wanted to protect and the bond with friends are overshadowed, can she still save her friend's sanity?",
  str_book_info1045 = [[
If the world has been engulfed by darkness, and there is no more light, then I will become the light that dispels the darkness.
That is Reinhardt's choice. He chose to be the light that shines in every corner, bringing hope to the mire of despair.]],
  str_book_info2001 = "Surrounded by the Four Angels, it seemed like there was no way out for Brock and Jona... But just at that moment, Jona devised a special escape route: jumping off of Lumopolis! Regardless of the outcome, at least they both got out of Lumopolis...",
  str_book_info2002 = "After escaping from Lumopolis, Jona and Brock managed to rendezvous with the Rediesel Wrench's forces. In the face of their pursuers, they dropped some choice one-liners and swaggered off, disappearing into the rolling yellow sands...",
  str_book_info2003 = "Bowlinger initiated self-destruction, and Sharona barely managed to escape with Philyshy on her shoulder. The two foes finally reconciled, and together, they resolved the hidden threat to Gannon City. Philyshy yawned again, but Sharona no longer rebuke her, and the two escaped the blast.",
  str_book_info2004 = "After a thrilling battle, Connolly acquired the troublesome little fellow and gained a new understanding of the word \"home.\" It was another uneventful day in the ordinary Holiday Cafe, but to Connolly, it was a precious slice of everyday life...",
  str_book_info2005 = "Northland, a magical snowy plain. Where the shining stars descend from the sky to adorn the crystal clear lake, where the purest snow blankets all dense forests and boundless plains alike. The Winter Palace stands tall in the frigid wind, like a celestial maiden reaching her slender, pale hands up towards Aurora.",
  str_book_info2006 = "Carleen's efforts finally pay off as she plunges her spear through the ultimate obstacle, and as the Eclipsite falls, she finally completes Bethlehem's trial. The path to become a guardian is arduous and lonely, and reserved only for those who possess true strength. However, as long as one looks up and gazes at the beautiful Aurora—only then can its irrefutable significance be comprehended.",
  str_book_info1051 = [[
Forsakin and Schummer stood before the healing pod.
Forsakin told her that as long as she relinquished all it meant to be a Caelestite, she could gain even more power.
All Schummer had to say on the matter, was that she had already given up on being a Caelestite a long time ago...]],
  str_book_info1052 = "In order to uncover Schummer's whereabouts and find a way to repair Soroz, you returned to the home of the Caelestites—\nEraveil",
  str_book_info1053 = [[
Finally, deep in Eraveil, you found the crashed Aviduz.
Forsakin had been waiting there for a long time, and it seemed she had something to say to you.
Or was she just... playing for time?]],
  str_book_info1054 = [[
The awakened Schummer greedily devoured the Eclipsites around her.
Although the taste was beyond disgusting, her determination to claim revenge pushed her past all preconceived notions of pain.]],
  str_book_info1055 = [[
Having obtained all-new power, Schummer wanted her teacher to accept this gift, but she was locked behind inescapable restraints.
However, such bondage could not stop Schummer, and she firmly believed that the Caelestites would eventually pray to her for a second chance.]],
  str_book_info1056 = [[
Through both internal and external subjugation, Eraveil fell.
The Eclipsites invaded wantonly, proclaiming the great coming of the Eclipse.]],
  str_book_info1057 = [[
Fueled by uncontrollable desire, Schummer broke through the Seed's limit, and Forsakin finally achieved her goal.
She took the Seed from Schummer without hesitation and left.]],
  str_book_info1058 = [[
Schummer ordered the Eclipsites to kill everyone while they were busy retrieving the Modules.
But having lost her Seed, she was soon surrounded by Eclipsites and died amidst a sea of shifting dark chaos.
Her end mirrored the suffering wrought upon her people seventeen years ago.]],
  str_book_info1059 = [[
In her last moments, some of Schummer's consciousness entered your mind.
You witnessed the shadows of the Eclipse. Although it was only for a moment, the extent of the power you sensed was unquestionable...]],
  str_book_info1060 = "With a loud noise, the door slowly opens before you. Secrets that have been buried under Eraveil for an entirety are waiting to be uncovered by you.",
  str_book_info1061 = "The Special Attacker is activated to deal with Eclipsites, but it targets Aurorians as well. Vice is hit by it trying to protect you.",
  str_book_info1062 = "You arrive at the core area deep in the underground base and found the Circular System that controls the entire base. This strange machine may just know how to save Vice who has fallen into Hibernation.",
  str_book_info1063 = [[
The Obelisk of Return rises in violent shocks, revealing its original appearance.
"This White Tower was never meant to be here. It should be... somewhere a lot higher."]],
  str_book_info1064 = "The risen White Tower has become the tallest structure in Eraveil. It stands here while you get to view the entire world through it.",
  str_book_info1065 = "The recent geological changes have made the road to the Chord Zone rugged and rough. Every step in the trap-filled tunnel is extremely difficult. In order to cure Vice, however, you have to overcome any difficulties that stand in your way.",
  str_book_info1066 = "Barton has gained a new power from the Chord Link, which allows him to once again go head to head with Forsakin and turn the tide. With his help, you drive away Forsakin and place Vice into the Chord Link, hoping that it will cure her...",
  str_book_info1067 = "Eraveil is in an unprecedented crisis. The Obelisk of Return being surrounded by Eclipsites reminds you of the day Eraveil was attacked. But it is different this time. Friends and allies from all over have come to your aid.",
  str_book_info1068 = "Vice who has fallen into hibernation was placed in the Chord Link for treatment. Give her time and have faith that she will wake up.",
  str_book_info1069 = "Carleen and you have woven a cocoon using the Obelisk of Return's layers of defense, to protect Vice who is inside the Chord Link in order to ensure that she will wake up as planned. Now is the time to break the cocoon.",
  str_book_info1070 = "Your allies are keeping Eclipsites out of the tower to ensure the operation runs smoothly. A battle has broken out between the Queen of the North, who has come afar, and Figelo. Every second counts now. Find an opportunity to turn the tide and bring victory and hope to this battle.",
  str_book_info1071 = "Vice who has awoken from the Chord Link seems to have gained new abilities. Your minds are connected at this moment. You have protected her all this time, and now, she will fight for you.",
  str_book_info1072 = "While the battle of Eraveil is over for now, everyone has different opinions on what to do with the Obelisk of Return. In the end, they manage to reach an agreement—The Obelisk of Return belongs to Eraveil and the Caelestites.",
  str_book_info1073 = "You run into Sean, Crow, and Zhao at the Illumina medical center. They have come from a remote town called Twilight located outside Illumina's defense line...",
  str_book_info1074 = "Four researchers from Illumina's top secret Science Council are waiting for you. How will this secret meeting change yours and Soroz's fate?",
  str_book_info1075 = "You see Soroz again in the data space. It is in front of you, but you can't touch it. Even the proximity is false.",
  str_book_info1076 = "According to ancient records, the Colossi returned from the skies. The world has long since become unfamiliar, leaving them no choice but to seek for traces of the past.",
  str_book_info1077 = "When the Aurorastorm surges out of control, knights tear across the crimson sky like brilliant silver comets. With the decorum of the Lumo Nobles no longer a consideration, these stalwart knights don their spiked suits of iron armor in defense of the people.",
  str_book_info1078 = "You enter Twilight and don't know where to look. Homeless people roam the streets, vendors hawk their goods, and Lumo knights and Illumina soldiers walk side by side on the streets.",
  str_book_info1079 = "Sean decides to challenge Axelia to see who can defeat more Eclipsites. In the end, Axelia wins!",
  str_book_info1080 = "This Colossus has been buried here for so many years that it has almost merged completely with the rocks around it. A giant that once soared in the blue skies above will never again spread its wings...",
  str_book_info1081 = "When you return, a Wraith you've never met before stands in your way. She has great power and a strange motive. She seems to want to destroy all \"desires\" in the world.",
  str_book_info1082 = "\"We meet again, Caelestite. I shan't hold back since you've come and delivered yourself right to me.\"",
  str_book_info1083 = "To complete her experiment and collect data, Forsakin decides to use Vice to uncover the secret of the Chord Link. When you try to stop her, you are pinned to the ground by the pet she carries everywhere with her.",
  str_book_info1084 = "Yingel plays her trump card against Forsakin and Helios—she threatens Forsakin with the destruction of the Chord Link. Facing the disdain and contempt of the other party, Yingel pulls the trigger.",
  str_book_info1085 = "Thinking that the lab has been destroyed, Forsakin hurriedly abandons her hostages to rescue the lab, only to realize Yingel has tricked her.",
  str_book_info1086 = "Forsakin uses three different enhancement methods to successfully turn Helios into the strongest existence. It's now time to test the stability of the subject by killing things.",
  str_book_info1087 = "The Joint Military Exercise is held as scheduled, and participants from Lumopolis, Illumina, Twilight, and all other places gather here to fight for the crown.",
  str_book_info1088 = "Up against waves of Eclipsites in the Battle Simulator, Leo's team still manages to emerge victorious, shocking everyone with their power.",
  str_book_info1089 = "Leo's team members seem to have exposed a weakness in the final flag capture battle. Yingel decisively grasps this fleeting opportunity to put an end to the battle.",
  str_book_info1090 = "Yingel's team, the champions, send Axelia to participate in an exhibition match with Reinhardt. Undercurrents surge beneath the seemingly peaceful atmosphere of the venue.",
  str_book_info1091 = "Even though you stop Figerald, a mysterious Wraith takes away the core console of Guardian One and says something vague in front of everyone. Who is she?",
  str_book_info1092 = "In the interrogation room in Illumina, the Reinhardt Treason Case undergoes its third internal scrutiny. The once-revered Grand Marshal Reinhardt, now shackled, silently gazes at the onlookers.",
  str_book_info1093 = "As the new Grand Marshal, Wrath, makes a grandiose entrance, she's surrounded by the Guard Legion and the state-of-the-art weaponry: Engine VII. Soldiers marvel at her unstoppable grace, yet a medley of emotions churns in her heart.",
  str_book_info1094 = "The quagmire relentlessly gnaws at the land, emitting deafening cracking. Surrounding earth mounds crumble, vegetation withers away, and a pungent stench fills the air. It's like an immense web ensnaring innocent creatures.",
  str_book_info1095 = "Within the rapidly spreading quagmire, the blood-red maw of an Eclipsite suddenly emerges. It rages wildly, preparing to devour both the land and the Aurorians. The soldiers panic, scattering in all directions.",
  str_book_info1096 = "Plunged into boundless darkness, Wrath has only a faint glimmer around her to rely on. It's the seed embedded in her back, like a drill, relentlessly draining her life force. The frailer she becomes, the more dazzling the seed's radiance.",
  str_book_info1097 = "The seed's expansion unfolds like a delicate thornflower's exquisite blossoming within Wrath's form. She feels the prickling sensation, akin to iron chains tightening around her, as if it were a punishment for her lost duel.",
  str_book_info1098 = "Although Axelia doesn't feel physical pain, the emotional anguish subtly intensifies each time she witnesses a soldier fall. One, two... she silently counts the number of deaths, giving rise to the illusion that she has perished eleven thousand, one hundred, and eleven times herself.",
  str_book_info1099 = "In the azure sky, several dazzling streaks of white light flash by. Joselyne, atop a snow-white warhorse and brandishing a sharp blade, speeds forth alongside the Lumo Skyriders, charging toward the quagmire. The sky echoes with the neighing of horses.",
  str_book_info1100 = "The Navigator pilots the Colossus to the designated location to perform a mission. After the Colossus flies to a safe height for final descent, Caelestites and Eclipsites start to descend from the sky. Is this a dream, or has this really happened before?",
  str_book_info1101 = "In the sky dyed red by the sunset, through layers of clouds and mist, a black hole that can devour everything watches you. It seems to be trying to tell you something, and you notice that it has left a dark black mark in your mind after you wake up.",
  str_book_info1102 = "Many frozen stone pillars seem to be growing towards the sky. Some sort of force seems to be guiding them into some form in the air. Why would a scene like this appear in the mind of an Illuminan who almost never leaves home?",
  str_book_info1103 = "One day, one year... three years, and then ten years... In that era of war, young Ulysses searched the evidence room for hope of the Aurorians' survival—hope that comes from a name that has been erased from the history of Illumina.",
  str_book_info1104 = "After 40 years of research, 20 years of which were spent compiling a special gene database, this warehouse is filled with Ulysses' creations prepared specially for this moment to fight against the enemy.",
  str_book_info1105 = "Enemies are running amok in Gannon City to find and eliminate the Caelestite. Just as they get close to the Caelestite, the Caelestite's petite and unassuming companion blocks a heavy strike from an enemy for the Caelestite without any hesitation.",
  str_book_info1106 = "\"Don't let them control you! Wisdom has no restrictions!\" Algol shouts as her mind operates at high speed with Bool. She wants to tell everyone that they don't have to live in a world that is constantly threatened by the unknown.",
  str_book_info1107 = "Trips are always mysterious and magical when traveling with Lady Victoria. She said that now that the Pristine River has been awakened and Eoria needs to start a new chapter, that special existence is needed to guide everyone in the same way.",
  str_book_info3060 = "The decisive blow was dealt! Smokey jumped up high! Before anyone had a chance to react, the volleyball blasted across the court like a bullet from the barrel of a gun, hitting her opponent head-on!",
  str_book_info3061 = "The strange competition had suddenly become a water gun battle, and everyone's going all in!",
  str_book_info3062 = "The Ocean Sovereign's final trial was a beachside performance! The Aurorians took turns to perform on the stage, and finally, the trio of Smokey, Carleen, and Vice—\"Kiss of the Manticore\"—delivered a stunning performance that electrified the entire audience.",
  str_book_info3063 = "Signs of the crisis still remained, and Beryl suddenly disappeared! When you finally found her again, she was in a world of danger!",
  str_book_info3064 = "When it seemed all hope was lost, Raphael leaped from the cliff and caught Beryl in midair. Angels really can fly!",
  str_book_info3065 = "After Raphael caught Beryl, she used her jets to slow their fall. How could anyone abandon their friends because of something as trifling as mortal danger?",
  str_book_info3066 = "Bonacie conducted a forbidden melody on the surface of the sea for her Holy Avatars to perform. As they did so, the castle sleeping at the bottom of the sea slowly rose behind her, and a huge meteorite fell from the sky, heading straight toward our heroes, the beach, and the Inn!",
  str_book_info3067 = "When it seemed all was lost, Fleur commanded his newly-developed giant robot and bore the brunt of the meteorite's impact with its hands! What kind of strange power is this?",
  str_book_info3068 = "The crisis had been averted. Fleur commanded his Rediesel Steel MkV to stand in front of everyone and blocked the surging waves.",
  str_book_info3069 = "During the final audience, the Colossus team fell at a disadvantage before the power of the formidable King and Caroline. Caroline proudly revealed her secret to Beryl, and Beryl, who had learned the truth from Raphael, fought back with all her might.",
  str_book_info3070 = "Having broken through the enemy's magic all by herself, Beryl used all of her strength to launch a final attack and defeated the King and Caroline with the help of her friends.",
  str_book_info3071 = "On the barren desert wastes stands a steel Illumina building—Undercity 24 Station. According to our reports, this structure is mainly used as a training ground for new recruits, and is also used as a transportation hub, containing warehouses and other facilities.",
  str_book_info3072 = "The moment the powerful Eclipsite boss is blown to pieces, the same thought passes through everyone's minds—the time to fight back has arrived!",
  str_book_info3073 = "Officer Brent leads the soldiers in a counterattack against the Eclipsites. However, a tentacle suddenly bursts out from the ground and pierces his chest.",
  str_book_info3074 = [[
There was a time when Gram couldn't think of a proper way to say goodbye to his fallen brothers-in-arms.
Now faced with Brent's sacrifice, Gram vows to carry forward Brent's stalwart conviction, promising to continue fighting until victory is theirs!]],
  str_book_info3075 = "A giant flying Eclipsite known among its kind as Hylingerr attacks Undercity 23. Unshaken by their foe's terrifying power, the people of Undercity 24 meet the enemy head-on, fueled by both determination and rage.",
  str_book_info3076 = "Communications have finally been restored, and everyone eagerly awaits news of the battle. After a short wait, Reinhardt, Grand Marshal of Illumina, appears on the screen and announces that the Dunefire Line has been successfully reestablished, and that Illumina has emerged victorious!",
  str_book_info3077 = "Before everyone leaves Undercity 24, the head officer suggests that they take a group photo to immortalize this momentous day. The photo captures the smiles of the soldiers, the light of Brent's undying hope, and the splendor of Illumina.",
  str_book_info3078 = "Faced with an Eclipsite army offensive, Officer Brent lays out the goal of the Undercity 24 squad as clearly as possible—all they need to do is face the Eclipsite army and defend the Undercity!",
  str_book_skin_info_1001 = [[
Do things exist in this world because we believe in them, or do we believe in them because they exist?
True or false, fact or fiction...
Does the castle Kleken mentioned really lie at the bottom of the sea, or is this just another of his stories?]],
  str_book_skin_info_1002 = [[
Vice plans to earn some extra money on the trip, and so she begins experimenting with several interesting attempts...
Being a good friend that you are, why don't you give her some encouragement, or perhaps some suggestions?]],
  str_book_skin_info_1003 = [[
Clearly afraid of the sea, Carleen closes her eyes when entering the water...
Fortunately, your outstretched hand lends her some courage, and she finally opens her eyes to enjoy the beauty of the ocean with you.]],
  str_book_skin_info_1004 = "A gift that can bring true happiness is priceless—this is Eicy's philosophy.\nIn order to repay you for the priceless gift you gave her, she prepared a whole load of treats for you and delivered them in person...\nThe problem is, these gifts are a little too sweet for anyone's taste.",
  str_book_skin_info_1005 = [[
The shipwrecked Barton drifts to a desert island, refusing to succumb to the ocean depths.
As long as he still draws breath, his training must go on!
In order to conquer the seas one day, Barton and his two white wolves run along the beach with unyielding vigor.]],
  str_book_skin_info_1006 = [[
As she looks out across the barren wasteland, Hiiro changes into the old Illumina Military Academy uniform you gave her.
A rare expression flashes across her face, becoming as gentle as the starry night sky.]],
  str_book_skin_info_1007 = [[
A graveyard lies hidden in the lush forest depths.
Sharona tells you that this is the resting place of her departed people.
She makes a point of emphasizing the fact that, although they were her people, they were not her family.]],
  str_book_skin_info_1008 = [[
Under Hiiro's orders, Vice lights the sparklers for the first time.
Their little sparks dance under the quiet night sky and light up Vice's face, which is flushed with excitement.
If only this moment could last forever.]],
  str_book_skin_info_1009 = [[
As raging flames surround, our hero smashes through the window without a second thought!
This is the magnificent climax of the breathtaking final scene.
If you were watching from the audience, you'd offer your thunderous applause.
Unfortunately, you happen to be the main actor this time.]],
  str_book_skin_info_1010 = "The sandcastle transforms into water droplets that reflect the setting sun in a kaleidoscope of pinks and reds, but this beautiful image is not quite as picturesque as her smile.",
  str_book_skin_info_1011 = [[
No matter how desperately Pact struggles to break free from the thorns, their clutch only grows tighter and tighter.
At that moment, you push open the door and witness her plight with your own eyes.
Pact blushes and shouts, "Don't look at me! I can handle this myself!"]],
  str_book_skin_info_1012 = [[
No escape!
Migard drags you into her room.
This weird lounge is full of strange plants and scientific apparatus and materials.
It seems... not at all that surprising.]],
  str_book_skin_info_1013 = [[
Green plants sway lightly under the midday sun.
Strands of cat hair float upon the air.
Sleeping soundly in the sun, enjoying a fine feline dream.]],
  str_book_skin_info_1014 = [[
As the clock strikes twelve, the magical illusion is gently stripped away by time.
A beautiful ball gown transforms into a kaleidoscope of butterflies, fluttering brightly in the warm light.
Until the last dance comes to an end.]],
  str_book_skin_info_1015 = [[
As magnificent ribbons dance in the air, the spirit of the season slowly takes hold.
Excitement, anticipation, and restlessness seep in.
After enduring the suspenseful countdown, no one can deny the joy of present time and finally opening the long-awaited gifts!]],
  str_book_skin_info_1016 = [[
As distant echoes of revelry approach the shore, they are scattered by the winds over Lake Mirror.
Nikinis lowers her head to gaze upon the lake's surface...
But her sister is nowhere to be seen. Instead, she is faced with a crystal clear reflection of herself.]],
  str_book_skin_info_1017 = [[
Life is like an illusion in the mirror.
Desire, yearning for what cannot be yours.
When turbulent thoughts pervade your mind, the best solution is to clear your head amid a sea of chaos and sink into a peaceful sleep.]],
  str_book_skin_info_1018 = [[
"Casting aside your worries is not as difficult as it sounds."
The waitress smiled cheerfully.
"All you need is somewhere warm, a hot drink, and someone to chat with you."
"And, of course, a good night's sleep."]],
  str_book_skin_info_1019 = "The courage of a lizard! Under the blinding sunlight and the vast desert, Maggie appeared boldly and even sent the performer flying. Not only did it shock the audience, but it also left them with a deep impression.",
  str_book_skin_info_1020 = "Warning! Eve's in danger! After putting on this strange outfit, no matter where Eve is, whenever she activates the device, Sinsa immediately appears by her side like a doting, old father... Oh wait, I mean like an older brother.",
  str_book_skin_info_1021 = "After much reflection and pondering in the light of the setting sun, Uriel, as always, was lost in her thoughts about nothingness. The only thing that can save her is your company. No matter the outcome, what matters is the time spent together.",
  str_book_skin_info_1022 = "Good or bad? Sariel, who pursues symmetry in everything, would rather rip a perfectly good stocking to achieve what she calls perfect symmetry.",
  str_book_skin_info_1023 = "Carleen changed into an outfit for the pajamas party that us completely different from her usual solemn and serious self! But don't stare at her. Even the knight commander would lose his composure if he did.",
  str_book_skin_info_1024 = "Shinnosuke is a samurai from the east. In order to restore the well-being of his sister, Eve, he has vowed to eliminate all evil from the world. During his journey, he encounters his nemesis—the Caelestite, and the two are locked in a fight to the death. Who will be the last one standing?",
  str_book_skin_info_1025 = "Vivian put on the Cloud Mountain outfit and took over as the Cloud Blossom Hotel's owner temporarily. With her help, the usually deserted inn began filling up with guests. However, she should learn to rest more!",
  str_book_skin_info_1026 = "Wearing a special combat outfit, Wrath arrived at Cloud Island and began her investigation quest. Only, isn't this outfit a little conspicuous? \"This must be Hiiro's idea!\" —Legion Commander Wrath.",
  str_book_skin_info_1027 = "A flamboyant maiden stands on the platform with her white parasol while writing her wish on a postcard. It'll be a wonderful holiday, provided that no unforeseen events occur. But don't worry. A trustworthy chief judge is always on standby!",
  str_book_skin_info_1028 = "Connolly attemps cheerleading, but finds herself unable to feel comfortable in her outfit. Thanks to the encouragement of those around her, she decides to overcome her qualms with a special \"workout,\" but then it starts raining...",
  str_book_skin_info_1029 = "The new outfit Istvan intended to use for the event gets replaced with a flashy suit. Despite the mocking it causes, he manages to pull off a perfect performance on the day of the event that takes the words out of his opponents' mouths.",
  str_book_skin_info_1030 = "\"Mere strength is no substitute for the power of justice.\" There's no need to follow the meaningless rules of a shady match or care about bogus rankings. Just give it your all and leave with a carefree attitude.",
  str_book_skin_info_1031 = "Taki is in the lead when the rally reaches the Umbraton group. However, his opponents refuse to be outdone and use some kind of \"lethal weapon\" to stall his car...",
  str_book_skin_info_1032 = "Louise relaxes on the grass, enjoying a delicious afternoon tea with her \"Mistress.\" This fairytale-like, happy life is what Louise believes a maid's life to be. After all, Lita told her so.",
  str_book_skin_info_1033 = "\"Thump Thump Thump...\" An accident makes Bethel's heart beat like drums. Is it because of fear, or the thrill of being inspired? Or could it be because of a crush? Perhaps... we can find the answer in Bethel's novel.",
  str_book_skin_info_1034 = [[
Fleur picked up the freshly baked bread, lowered his head and took a bite, then chewed on it carefully. Suddenly, he froze in place, eyes filled with tears...
"Thank you for helping me find that warm taste."]],
  str_book_skin_info_1035 = "This is no joke. I repeat, this is no joke! This is a sudden maid tactical exercise. Prisoners who break into the manor will be brought to justice and put in prison. All the maids, including the Head Maid, all have full confidence in that.",
  str_book_skin_info_1036 = "Most people find airy, dreamy things soothing, and Leona is no exception. She finds rare peace of mind when encapsulated by a giant bubble, which is perhaps a state of mind she has long searched for.",
  str_book_skin_info_1037 = "There is something about her that is as dazzling and breathtaking as a gem. Witnesses find it difficult to pinpoint the exact source of her charm.",
  str_book_skin_info_1038 = "If someone on the island commits evil and no one will listen to the victim's complaints, the victim can pour out their grievances to the sea, who shall send envoys to preside over justice. This time, the one who has been sent is...",
  str_book_skin_info_1039 = "It is extremely cruel and selfish to nail a \"rainbow\" in a wooden box to keep its beauty all to yourself. If you truly want to appreciate that rainbow, you must let it dance freely.",
  str_book_skin_info_1040 = "Clear water and freely swimming aquatic creatures... When looking at them, Gronru seems to be able to forget her identity and the games she used to love. At this moment, she is just a little girl who is happy after seeing something she has been thinking of.",
  str_book_skin_info_1041 = "Swimming in the desert, you say? Nothing is impossible! Members of the Rediesel Wrench are hosting a water festival at the Oasis. And the timely delivery of Azure's request brings the festive atmosphere to a new level.",
  str_book_skin_info_1042 = "\"I should be taking every life without a second thought.\" W-Wait, what's this? Pointing a gun at an old friend?! What are you doing, Charon?! The look in his eyes tells me he isn't playacting...",
  str_book_skin_info_1043 = "\"The living tell a thousand lies, but the dead tell nothing but the truth. A shame no one can hear their voices.\" Ignoring the sideways glances and whisperings of others, Sikare helps uncover the truth to give voice to the deceased.",
  str_book_skin_info_1044 = "Though she does not belong to the Illumina Federation, Hedy's new Illumina sheriff uniform fills her with confidence and a sense of duty. As such, even her speech garners the respect and admiration of the masses.",
  str_book_skin_info_1045 = "\"This was a bigger let-down than I thought...\" Even in a dangerous place full of hardened criminals, Revy's power makes her stand far above the rest. When one is so undefeated in strength, the lack of competition must get lonely at times.",
  str_book_skin_info_1046 = "\"Boss, this is for you.\" With her second-in-command and other members, Paloma looks just like a gang leader. Under everyone's quick glances, she is already thinking of how to respond to the visitor's request.",
  str_book_skin_info_1047 = "Although Shaya also showed a willful and girlish side in the story, she is now focused, responsible, and very determined, just like Bethlehem, and charming in a different way.",
  str_book_skin_info_1048 = "Rally yourselves up, everyone, for The Punisher is here! Punishment in the form of flashing lights and sonorous thunder accompany her as she raps her way before you! Under her sharp surveillance, none shall escape!",
  str_book_skin_info_1049 = "\"This piece is dedicated to everyone in the audience.\" Music brings them warmth and blessings on this cold winter's night. And for a special audience member, it also brings acknowledgement and encouragement.",
  str_book_skin_info_1050 = "In order to gain an advantage, Siobhan calculates data on all the contestants and quickly formulates her own strategy—to build on her charm by using clothing and makeup and dominate the auditions.",
  str_book_skin_info_1051 = "Aromantic? Too serious? Perhaps the demeanor is just a front. Pittman shows his soft side when two hearts long for each other, and the white dove is the testimony to that.",
  str_book_skin_info_1052 = "The famous Thunder Knight lived up to her name by striking the \"enemy\" with a lightning bolt in the blink of an eye. Much to her surprise, however, the guy professed his love for Michael out of the blue...",
  str_book_skin_info_1053 = "She's both the salon's owner and the game's banker and participant. Jeno now understands the rules here. After that, he showed his despicable opponent the true magic, creating a miracle that sent the Joker card to where it should go.",
  str_book_skin_info_1054 = "\"All of you—you're all under arrest!\" When faced with a suspect foolish enough to try stalking her sister, Dayna opted for the most direct and effective solution—to arrest everyone present and not let a single one of them go.",
  str_book_skin_info_1055 = "Could that unignorable presence lurking behind Fia in the darkness really be a dragon...? After calming down sufficiently, she realizes it is just some kind of device... but who controls it?",
  str_book_skin_info_1056 = "The best way to deal with a truly contemptible person is to use their own dirty tricks against them—give them a taste of their own medicine. And when they finally realize just how treacherous and vile they are, it'll already be too late.",
  str_book_skin_info_1057 = "Amidst a sea of flowers, the fallen Cuscuta ensnares the wicked criminal and drags him into the abyss of doom, while the fragrance becomes a funeral dirge for the sinner.",
  str_book_skin_info_1058 = "\"Don't run away from me.\" Eicy says with an innocent smile, as she calmly navigates through the frantic crowd. Despite being the mastermind behind it all, in her own way, she sees it as an act of mercy.",
  str_book_skin_info_1059 = "It turns out that the forbidden spell inscribes in the grimoire is actually a recipe for a delicious dish. Unusual ingredients harmoniously blend together, creating an extraordinary flavor that bestows a divine essence upon those who taste it.",
  str_book_skin_info_1060 = "Not all who possess great power are evil. It all depends on how that power is wielded. In order to safeguard the innocence of the children, Gabriel makes a resolute decision and discovers the motivation to persevere.",
  str_book_skin_info_1061 = "It seems that Rinne is asking her friends for help after getting wounded and is promising to repay them well according to the customs of Cloud Island. However, is this person really Rinne?",
  str_book_skin_info_1062 = "Paloma can't care less about the opinions of others and never bothers with worldly conventions. She just leisurely embraces the coastal vibes, confidently showcasing her attire, as her charm gracefully disperses.",
  str_book_skin_info_1063 = "When you make a wish on an intact dandelion and then blow it away, your wish will come true as the first dandelion seed lands. She whispers in her mind, and watches the white fluff. At that very moment, the wish has already come true.",
  str_book_skin_info_1064 = "The exploration of ruins is fraught with peril, especially underwater, where even seemingly harmless water grass can become a deadly noose. Luckily, Florine is here, ensuring such scenarios never come to pass.",
  str_book_skin_info_1065 = "The waves washed up the drift bottle into her hands. With no intended recipient, the drift bottle isn't a means of relaying messages but symbolizes someone's desire. But at this very moment, it seems the waves are no longer mere waves but a member of the esteemed Courier Union.",
  str_book_skin_info_1066 = "The ice drakes glide through the arid air, bringing here refreshing breezes, and on the surface of the sea, gleaming, chilly crystals begin to condense... Only the almighty Queen of the North could create such a wonderful, magnificent scene on a scorching beach at the height of summer.",
  str_book_skin_info_1067 = "These floating jellyfishes seem to be incredible to everyone's eyes, but the luminescent sea they formed here and now are even more fantastic than one could see in any fairy tale.",
  str_book_skin_info_10045 = "She's the lofty, distant, and unsmiling Chief Judge to everyone else. But right now, she's showing a completely different side of her, one that she keeps well hidden beneath her mask...",
  str_book_skin_info_10046 = [[
As the rain clears and the sun emerges, the two stroll along the dampened shore.
Seeing the dark clouds gradually dissipate, a ray of sunlight shines on the azure sea and golden sand.
The only thing more wonderful than this would be if they could see this beautiful scenery too.]],
  str_book_skin_info_10047 = [[
Surroundings that are constantly changing, the eerie chiming of a clock, and this sudden illusion...
Sanae is scared beyond belief.
It's only by staying close to the Navigator that she has the courage to keep moving forward.]],
  str_book_skin_info_10048 = [[
Nina still feels that many of her ideas have not been realized after she took several series of photos.
She decides to follow the advice of the Navigator and have a rest after her busy work, but the gloom still haunts her.]],
  str_book_skin_info_10049 = "Connolly walks out of the fitting room adjusting her dress, an anxious expression hanging from her face. Although she really likes this outfit, she'll need to wear it to welcome the others, and just the thought of the Navigator's gaze fixed upon her sets her nerves on edge. Now, all she wants to do is find a dark corner to hide in.",
  str_book_skin_info_10050 = "As twilight envelops you, you huddle around the campfire, reflecting on recent experiences. You listen in silence as Gram shares his stories of the young soldiers he encountered after becoming an instructor: Some carved their paths to glory, while others met untimely ends in recent battles.",
  str_book_skin_info_10051 = "As the Eclipsite Vacuum Cleaner roars to life, Revy swiftly defeats all enemies in front. Then, as per Gronru's request, Revy promptly strikes a dashing pose, and Gronru seizes the moment to wrap up the advertising shoot.",
  str_book_skin_info_10052 = "They have finally dug a hole, and Ciel comes face to face with you and Gronru. Despite knowing that Ciel will be safe, Gronru offers her a comforting embrace to alleviate her nervousness. With Ciel's emotions calmed, she will proceed to guide the team through the upcoming mission.",
  str_book_skin_info_10053 = [[
Hearing the mixed sounds of shouting sailors and ships leaving the port, Dantang could feel the sailors' enthusiasm for adventure from where she was standing in a pavilion.
However, when it's time for them to return, some of these ships return to the port with gold, silver, treasures, and exotic stories, while some ships never return. That's why Dantang would silently pray for the ships going out to sea from the port as she held on to a red railing while watching them depart.
Although sailing out to sea is an adventure and journey for the brave, don't forget that there's always someone watching on from behind you, waiting for their loved ones to return.]],
  str_book_skin_info_10054 = "Little did Sariel expect that her accidental fall would not only resolve the trouble at the gaming house but also result in her commission reward going down the drain. Is this luck or misfortune? Regardless, Sariel considers herself fortunate to have faced the crisis with the Navigator.",
  str_book_skin_info_10055 = [[
A blade is easy to draw but difficult to sheath, as the heart, and not the hand, is the key to using a blade. Even the sharpest blade would be no match for a heart such as this because the bamboo leaves would already have fallen by the time the thought arises...
The blade has yet to be drawn.]],
  str_book_skin_info_10056 = [[
"Blessed by destiny, the Dragon Maiden brings auspicious tidings as she descends upon the world."
"The vast ocean's waves are obscure, as though shrouded in smoke."
"The Dragon Maiden, a gift from the heavens, bears countless blessings for all."
"Like a young moon slowly growing fuller, or the brilliant sun in its ascent."
"The Dragon Maiden, a gift from the heavens, bears countless blessings for all."
"Like a young moon slowly growing fuller, or the brilliant sun in its ascent."]],
  str_book_skin_info_10057 = "Sariel was so full of joy, she didn't notice that the clothing prepared for her by the store was despairingly asymmetric until she put them on. As someone with obsessive-compulsive tendencies, it instantly felt as if needles were pricking her entire body, and she wanted to tear off the atrociously unbalanced fabric immediately. However, she only dared to tug at the hem of the skirt to vent her dissatisfaction because the store would have made her pay for damages.",
  str_book_skin_info_10058 = "The merman soldiers behind Tianxian chased after him desperately to strip the glamorous clothes of the Dragon Palace off him and throw him into prison. Tianxian is in no mood to argue, and the most important thing to him now is to escape from the Dragon Palace. However, to people who have experienced the vicissitudes of life, getting into the palace is easy, but getting out is an entirely different matter...",
  str_book_skin_info_10059 = "The freshly baked festive cookies exude an alluring aroma, and the faint heat emanating is sufficient to dispel the coldness in the house. The cookies were baked by the children of the orphanage, and Lilica shared them with you because she thinks you deserve half the credit for the successful performance. May this cookie dispel the chill and bring you good luck in this cold weather.",
  str_book_skin_info_10060 = "With lightning-fast speed, Hiiro draws her blade and turns the attackers to dust, leaving no sign of their existence. Her elegant attire makes her awe-inspiring presence even more picturesque.",
  str_book_skin_info_10061 = "The quiet light of the bonfire casts a strange color on Hiiro's face. Perhaps it is the color of cherry blossoms that bloomed early in a distant place, or the color of powerful emotions that this beautiful lady is too shy to express.",
  str_book_skin_info_10062 = "Pollux recounts to you how past crises prompted her to become a protector. She does not want to dwell on the memories, though, as she anticipates creating a better future with you.",
  str_book_skin_info_10063 = "While Areia truly enjoys the wonderful time with you in the dreams, they are destined to vanish. The reality has plunged her into confusion. After bathing in genuine sunshine and breathing a refreshing sea breeze, Areia at last understands that kindness and bliss have always been around her.",
  str_book_skin_info_10064 = "Xuan Ji presents you with this parasol, as well as the dream it represents. Whether it's a faraway land or the ever-distant stars above, nothing is truly out of reach as long as you desire it.",
  str_book_skin_info_10065 = "Every sentence, every word, every character from the past could potentially be a sign left behind by our predecessors on their journey toward the truth. What shaped each character and what meaning it could possibly hold—answers all lie within each stroke.",
  str_book_skin_info_10066 = "What could be more comfortable than lying here in bliss?\nNo tasks to complete, no battles to fight, and no need to seek out a meaning for anything—the sole meaning of this moment is simply to let go and enjoy.\nSee, even the white dove fluttering outside my window agrees.",
  str_book_title_skin_50001 = "Day at the Aquarium",
  str_book_skin_info_50001 = "Did this outfit come first, or did the game that this outfit accompanied come first? It doesn't matter anymore. The important thing is that Gronru prepared this especially for her vacation and entered holiday mode right away after wearing it. Even if she is just going to the aquarium for a day and not the beach.",
  str_book_title_skin_50002 = "Fluffy Serendipity",
  str_book_title_skin_50003 = "Born to Act",
  str_book_title_skin_50004 = "Sweet Melody's Embrace",
  str_book_title_skin_50005 = "Tipsy Whimsy",
  str_book_saiji_info_20001 = "In Eve's memory, this is her happy home. But something was missing. Perhaps something had been forgotten, or maybe someone had been lost...",
  str_book_saiji_info_20002 = "Memories have finally been cleared, and Eve has been reunited with her beloved family. Hope and happiness, thriving in the sun, have become blooming white flowers.",
  str_book_saiji_info_20003 = "Eve \"wakes\" from an intense dream, and finds herself in a familiar, yet simultaneously unfamiliar, environment. Is this her own room?",
  str_book_saiji_info_20004 = "A huge steel crawler creeps on the mountaintop. Who is the creator of such a machine? And to what end was it constructed? A sense of deja vu washes over Eve; the sight appears familiar, yet she cannot pinpoint where she has encountered it before...",
  str_book_saiji_info_20005 = "Just as imminent collapse threatened Eve, a shield of familiar white flowers and sturdy vines emerged mysteriously. Where could they possibly have sprouted from?",
  str_book_saiji_info_20006 = "The two Eves finally join hands, prepared to confront their true reality.",
  str_book_saiji_info_20007 = "The warped world vanished, leaving Eve with a sense of relief. Though the path forward might be strewn with obstacles, it also shimmers with boundless potential.",
  str_book_saiji_info_20101 = "Sunlight streams through the colored glass, piercing the dim, silent room and casting a dazzling array of colors. It gently brushes against Irridon's eyelids, and she opens her eyes. That's when she sees it, a reflection of a woman in the mirror.",
  str_book_saiji_info_20102 = "Irridon knows the person in the mirror isn't herself, but for some reason, she feels her destiny is tightly entwined with that of the reflection. Then the candle's flame ignites, lighting up the pure and tranquil image of a nun on the wall.",
  str_book_saiji_info_20103 = "Irridon recalls the identity of the figure in the mirror and finally remembers who she herself is. The candle on the other side is lit, revealing a solemn and imposing image of the Chief Judge on the mural.",
  str_book_saiji_info_20104 = "Gazing at her reflection in the pool, Irridon suddenly feels a moment of introspection... What has led her to become who she is today? Is the reflection in the pool truly the image she aspires to be?",
  str_book_saiji_info_20105 = "The woman in black before her leaps into action, followed by numerous thorny vines surging forth from all directions. Irridon understands that the woman carries a darkness sharper and blacker in her heart than these thorns.",
  str_book_saiji_info_20106 = "In any case, Irridon cannot stand idly by and watch as the woman before her commits such a grave mistake.",
  str_book_saiji_info_20107 = "Victory over oneself is no easy feat, but Irridon has ultimately achieved it.",
  str_book_saiji_info_20108 = "This arduous trial has finally drawn to a close. Though the path ahead is long, Irridon will no longer be lost.",
  str_book_cg_no_collect = "Not Collected",
  str_book_cg_no_collect_msg = "Complete {1}{2} scenario to unlock.",
  str_book_world = "World",
  str_book_btn_pic = "Images",
  str_book_btn_lock = "-Not Collected-",
  str_book_role_dont_have = "This intel has not been collected.",
  str_book_monster_dont_have = "This intel has not been collected.",
  str_book_btn_monster_lock = "-Not Collected-",
  str_book_main_mark = "Emblem Wall",
  str_book_main_huodong = "Event Recap",
  str_book_main_lock = "Locked",
  str_book_ext_cg_active = "Complete the extra chapters to unlock.",
  str_book_main_cg_active = "Complete the main chapters to unlock.",
  str_book_pet_skin_cg_active = "Complete Collector's Outfit scenario to unlock.",
  str_book_pet_skin_cell_cg_active = "Unlocks after purchasing the Collector's Outfit.",
  str_book_cg_pet_skin = "Outfit",
  str_book_no_camp = "-No Faction-",
  str_book_not_open = "Temporarily Locked",
  str_book_main_medal = "Stand By Me Medallion",
  str_book_season_cg_active = "DNT",
  str_book_unlock_desc_20001 = "Obtained after reading the prequel of N1-Bizarre Dream in Awakening in the Storm",
  str_book_unlock_desc_20002 = "Obtained upon acquiring the collectible Complete Sketchbook in Awakening in the Storm",
  str_book_unlock_desc_20003 = "Obtained after reading the prequel of N1-Bizarre Dream in Awakening in the Storm",
  str_book_unlock_desc_20004 = "Obtained after reading the prequel of N7-Red Hound in Awakening in the Storm",
  str_book_unlock_desc_20005 = "Obtained after reading the sequel of N8-Catch Fire in Awakening in the Storm",
  str_book_unlock_desc_20006 = "Obtained upon acquiring the collectible Complete Sketchbook in Awakening in the Storm",
  str_book_unlock_desc_20007 = "Obtained upon acquiring the collectible Complete Sketchbook in Awakening in the Storm",
  str_book_unlock_desc_20101 = "Obtained after reading the prequel of N1 - Knight in Trials Amongst Golden Ripples.",
  str_book_unlock_desc_20102 = "Obtained after reading the prequel of N10 - Rebellious Conspiracy in Trials Amongst Golden Ripples.",
  str_book_unlock_desc_20103 = "Obtained after reading the sequel of N15 - Final Judgment in Trials Amongst Golden Ripples.",
  str_book_unlock_desc_20104 = "Obtained after reading the prequel of N1 - Knight in Trials Amongst Golden Ripples.",
  str_book_unlock_desc_20105 = "Obtained after reading the prequel of N14 - The Reflection in Trials Amongst Golden Ripples.",
  str_book_unlock_desc_20106 = "Obtained after reading the prequel of N14 - The Reflection in Trials Amongst Golden Ripples.",
  str_book_unlock_desc_20107 = "Obtained after reading the sequel of N15 - Final Judgment in Trials Amongst Golden Ripples.",
  str_book_unlock_desc_20108 = "Obtained after reading the sequel of N15 - Final Judgment in Trials Amongst Golden Ripples.",
  str_book_title_skin_10068 = "Tipsy Invitation",
  str_book_skin_info_10068 = [[
"A witch's time is valuable and I can't wait, tsk-tsk."
After drinking a magical potion, Uriel suddenly becomes proactive, not only cornering you but also attempting something even more dreadful...]],
  str_book_title_skin_10069 = "Bells in Dusk",
  str_book_skin_info_10069 = "\"I myself just realized—and it really is a second ago—that the emptiness could be filled.\"\nThe flames' heat blurs the witch's figure. But which of her is confessing to you right now?",
  str_book_title_skin_10067 = "Axelia's Sensibility",
  str_book_skin_info_10067 = "A magical feeling has struck Axelia, intertwining her fractured self with the rose confined in the glass jar. This inexplicable surge of emotion actually signals the burgeoning changes in her mindset.",
  str_book_title_skin_10070 = "Cherished",
  str_book_skin_info_10070 = "\"It was a wheat field! Full of golden, swaying grains, and I was standing in it! Next to me was a gentle lady whose face wasn't clear to me, but she was smiling at me. Many kids were running around us... Their laughter echoed through the field like a song.\"",
  str_book_title_skin_10071 = "Dragon Idol's Witness",
  str_book_title_skin_10072 = "Robyn's Midday Nap",
  str_book_skin_info_10071 = [[
"It might be a little arrogant of me to say, but I really hope I can become someone you can depend on."
Under the dragon idol's witness, you extend an invitation to Sharona.]],
  str_book_skin_info_10072 = "Lost in the world of books, Robyn nods off on the table. The midday sunlight is radiant, but her sleep is undisturbed.",
  str_book_info1108 = "Wish",
  str_book_info1109 = "Shatter the Darkness",
  str_book_info1110 = "Haven",
  str_book_info1111 = "Haven - Beacon",
  str_book_info1112 = "Vows on the Ridge",
  str_book_title1108 = "Shouldering an unspeakable duty, she kneels in front of the altar, her sorrow unvoiced but deeply felt, offering fervent prayers to the divine. This mysterious and poignant ritual unfolds like a melancholic masterpiece.",
  str_book_title1109 = "Amidst the darkness, she leaps up like lightning, her spear plunging mercilessly into the enemy's skull. With untamed ferocity and strength, she shakes the very earth, her eyes aflame with vindictive hatred searing her adversaries.",
  str_book_title1110 = "Led by the spirit of the mountains, the power of nature flows into the base, and clusters of flowing light burst forth from the tree stumps, illuminating the vast altar. Thus, the long-silent spirits are awakened.",
  str_book_title1111 = "In an instant, three ancient snow pines sprout into a towering tree like a beacon, its radiant glow illuminating the entire cavern, with the gentlest ray infusing Tiare's spear.",
  str_book_title1112 = [[
"To erect beacons along the path ahead."
The fluttering banner bears witness and cheers for them, carrying their vows to distant lands.]],
  str_book_title_skin_10073 = "Light of Fluorite",
  str_book_skin_info_10073 = "You chat late into the night with Fleur about minerals when the ore emits a faint glow—wait, why is it still warm? Judging from Fleur's face, could he be running a fever?",
  str_book_title_skin_10074 = "Dormitory Games",
  str_book_skin_info_10074 = "\"Now that I've caught you, you have to touch the heart on the table to get free!\"",
  str_book_title_skin_10075 = "Sleepless Starry Night",
  str_book_skin_info_10075 = "\"With you by my side, no matter how dark it is, I don't think I have anything to fear!\"",
  str_book_title_skin_10077 = "Sleeping Beauty & the Prince",
  str_book_skin_info_10077 = "\"Am I still dreaming? Everything feels too real, from your warmth to your breath...\"",
  str_book_title_skin_10078 = "Let's Do This",
  str_book_skin_info_10078 = "The door opens suddenly, interrupting the girl's hesitant steps. In that case, she can only bite the bullet and walk forward with her head raised high. The girl purses her lips, determined not to let anyone see her confusion and helplessness.",
  str_book_title_skin_10079 = "Dragon Maiden River Snail Dance",
  str_book_skin_info_10079 = "\"By performing her sacred dance here, the snails will do as I command out of reverence.\"",
  str_book_title_skin_10080 = "Caged Beast",
  str_book_skin_info_10080 = "Hydrad has infiltrated their ranks alone and is relying on you to come with reinforcements.",
  str_book_title_skin_10081 = "Tiny Deity",
  str_book_skin_info_10081 = "\"Your offering pleased me greatly. Speak your wish, and I shall grant it for you.\"",
  str_book_title_skin_10082 = "Flourishing Colors",
  str_book_skin_info_10082 = "\"May all the beauty of the world dance to your name, and may your wise leadership flourish for a thousand years.\"",
  str_book_title_skin_10084 = "Observer Yingel",
  str_book_skin_info_10084 = "\"As you can see, I'm observing the Rediesel Wrench in their natural habitat.\"",
  str_book_title_skin_10085 = "Performing with Barbara",
  str_book_skin_info_10085 = "Barbara's concert kicks off with a bang! \"The Last Caelestite\" is truly debuting with her?",
  str_book_title_skin_10086 = "Jeriah at the Beach",
  str_book_skin_info_10086 = "\"Whether it's you or our surroundings... It's all new to me.\"",
  str_book_title_skin_10087 = "Banquet's Star",
  str_book_skin_info_10087 = "\"Approaching him is perfectly acceptable, but I ask that you conduct yourselves with a bit more dignity.\"",
  str_book_title_skin_10088 = "Silhouette of Enlightened Illumination",
  str_book_skin_info_10088 = "\"As Grand Marshal of the Illumina Federation... I vow to watch over everything.\"",
  str_book_title_skin_10090 = "Unyielding to Time",
  str_book_skin_info_10090 = "\"The kids of the 2nd Legion... Have you become the stars that light others' paths?\"",
  str_book_title_skin_10091 = "White Flower Twins",
  str_book_skin_info_10091 = "\"We look so much alike; even our parents have a hard time telling us apart...\"",
  str_book_title_skin_10092 = "Sand Sprint",
  str_book_skin_info_10092 = "\"The gun is now shooting water instead of flames. If... only this kind of fun could last forever. An eagle can still soar high even with its claws tucked away.\"",
  str_book_title_skin_10095 = "Ryza's Lazy Day",
  str_book_skin_info_10095 = "\"You called me? What's up?\"",
  str_book_title_skin_10096 = "The Fireworks in Her Eyes",
  str_book_skin_info_10096 = "\"Fireworks may be brief, but they'll forever flicker in my heart.\"",
  str_book_title_skin_10097 = "The Drenched Dignitary",
  str_book_skin_info_10097 = "\"I mean, if you were to ask as sincerely as you did before, I, a noble, might spare some time to have fun with you.\"",
  str_book_title_skin_10099 = "Chance Encounter: Snowball",
  str_book_skin_info_10099 = "\"Please follow the direction I'm guiding you toward. Feel the floatation of the waves. Don't be afraid, I'll hold your hand.\"",
  str_book_skin_info_laisha = "Ryza's Lazy Day",
  str_book_title_skin_laisha = "\"! What's wrong?\"",
  str_book_skin_info_laisha1 = "The Fireworks in Her Eyes",
  str_book_title_skin_laisha2 = "\"Fireworks may be brief, but they'll forever flicker in my heart.\"",
  str_book_info_laisha1 = "Waveswept Rendezvous",
  str_book_title_laisha1 = "\"I thought we were playing, weren't we? Better get moving, or I'll really let you have it! Hah!\"",
  str_book_info_laisha2 = "Gathering Thoughts",
  str_book_title_laisha2 = "\"How about it? Can you feel our determination now?!\"",
  str_book_info_laisha3 = "New Adventure! Set Sail!",
  str_book_title_laisha3 = "The island lies silently at the bottom of the sea, along with the evidence of its former glory. Now, a new summer adventure is about to begin.",
  str_book_title_skin_10100 = "Ambitious Proposal",
  str_book_skin_info_10100 = "Got a Date? Don't Forget to Bring Some Gold!",
  str_book_title_skin_10101 = "Crimson Indulgence",
  str_book_skin_info_10101 = "Return of the Crimson Banquet",
  str_book_title_skin_10102 = "Steel Strokes",
  str_book_skin_info_10102 = "Relax! Take a Nutrient Potion!",
  str_book_title_skin_10103 = "Avaricious Lachesis",
  str_book_skin_info_10103 = "\"Beneath her graceful and tantalizing charm, a greedy light flickers. Stay wary, or she'll snatch away everything you hold dear!\"",
  str_book_info1113 = "Live Free or Die",
  str_book_title1113 = [[
"Her 'heart' blazes on, never tiring in its pursuit of freedom.
She will give her life for this truth.
'Live free or die,' said Lady Pepita."]]
}
